blocks.x:
/* Comentari d'una línia */
p {
  font-size: 10pt;
  background-color: gray;
  border: 1px solid blue;  /* para ver la caja */
}
h1, h2, h3 { font-family: sans-serif; }
* { margin: 0; }  /* universal */

p { font-size: 1.2em; width: 50%; margin: 10px; }
h1 { font-size: 24pt; }
.a { color: red; }
.b { color: #ff0000; }
.c { color: rgb(255,0,0); }

p {
  font-family: "Times New Roman", serif;
  font-size: 14px;
  font-weight: bold;
  font-style: italic;
  color: #333;
  text-align: center;
  text-decoration: underline;
  line-height: 1.5;
  background-color: #eef;
  background-image: url("fons.png");
}

div {
  width: 300px;
  padding: 10px;
  border: 2px solid blue;
  margin: 20px;
}
/* Atajos de padding / margin */
.a { padding: 2em; }                 /* todos */
.b { padding: 1em 2em; }             /* sup/inf , der/izq */
.c { padding: 1em 2em 3em; }         /* sup , der/izq , inf */
.d { padding: 1em 2em 3em 4em; }     /* sup der inf izq (reloj) */
.e { border-style: dotted solid double; }

img { float: right; margin: 0 0 10px 10px; }
.columna { float: left; width: 48%; }
footer { clear: both; }
.oculto { display: none; }
.en-linia { display: inline; }
.bloque { display: block; }

.rel { position: relative; top: 10px; left: 20px; }
.pare { position: relative; }
.abs { position: absolute; top: 0; right: 0; }
.fix { position: fixed; bottom: 10px; right: 10px; }
.stk { position: sticky; top: 0; }

img[title] { margin-right: 10px; }
img[title][class="preferent"] { margin-right: 10px; }
img[alt~="logo"] { border: solid; }
p[lang|="en"] { font-family: "Times New Roman", serif; }

a:link    { color: blue; }
a:visited { color: purple; }
a:hover   { color: red; }
a:active  { color: orange; }
input:focus { background: yellow; }
li:first-child { font-weight: bold; }
p:first-line   { color: green; }
p:first-letter { font-size: 2em; }
h2:before { content: "» "; }
h2:after  { content: " «"; }

@import "mes_estils.css";

@media print  { body { font-size: 10pt; } }
@media screen { body { font-size: 12pt; } }
@media screen, print { body { line-height: 1.2; } }
@media (max-width: 600px) { nav { display: none; } }

/* estils.css */
body {
  font-family: Arial, sans-serif;
  background-color: #f4f4f4;
}
h1, h2, h3 { color: navy; }
p {
  text-align: center;
  color: red;
}
a:hover { color: orange; }
.destacat { font-weight: bold; }
#principal { margin: 0 auto; width: 80%; }
